def metric_tool(query: dict[str, Any]) -> dict[str, Any]:
    """注入 E 的 ``metric_tool``：``dict -> dict``。

    成功时必须返回 ``metric`` / ``value`` / ``source_ids`` /
    ``period_start`` / ``period_end`` / ``queried_at`` 六键且 ``source_ids``
    非空（E 会据此生成 citation 与 ``metric_result``）；**当前所有指标的数据
    源都还没接通（卡 C 的观测/视频接口），因此一律走「不足」分支**——
    宁可让 E 说「无法核实数值」，也不拿历史资料或旧快照顶替当前值。

    等 C 的 08/09/23 落地后，只需在本函数内按 metric 分支补 resolver，
    返回形状不变，E 侧零改动。
    """
    if not isinstance(query, dict):
        return _unavailable(REASON_INVALID_ENTITY, detail="查询体必须是对象")

    metric = query.get("metric")
    spec = METRIC_CATALOG.get(metric) if isinstance(metric, str) else None
    if spec is None:
        return _unavailable(
            REASON_UNSUPPORTED_METRIC, metric=metric if isinstance(metric, str) else None,
            detail=f"指标不在字典内，可用：{', '.join(SUPPORTED_METRICS)}",
        )

    grain = query.get("grain")
    if grain not in spec["grains"]:
        return _unavailable(
            REASON_UNSUPPORTED_GRAIN, metric=metric,
            detail=f"{metric} 不支持粒度 {grain}，可用：{', '.join(spec['grains'])}",
        )

    entity_ids = query.get("entity_ids") or []
    if not isinstance(entity_ids, list) or not entity_ids:
        return _unavailable(REASON_INVALID_ENTITY, metric=metric,
                            detail="必须指定至少一个 entity_id（对象白名单内）")
    if len(entity_ids) > MAX_ENTITY_IDS:
        return _unavailable(REASON_INVALID_ENTITY, metric=metric,
                            detail=f"单次最多 {MAX_ENTITY_IDS} 个对象")
    if not all(_is_uuid(e) for e in entity_ids):
        return _unavailable(REASON_INVALID_ENTITY, metric=metric,
                            detail="entity_ids 必须是 UUID")

    start = _parse_period(query.get("period_start"))
    end = _parse_period(query.get("period_end"))
    if start is None or end is None:
        return _unavailable(REASON_INVALID_PERIOD, metric=metric,
                            detail="period_start / period_end 必填且须为带时区的 ISO 8601")
    if start >= end:
        return _unavailable(REASON_INVALID_PERIOD, metric=metric,
                            detail="period_start 必须早于 period_end")

    # 数据源未接通：明确报不足。注意 **E 会把整个 result 原样塞进
    # metric_result 回给前端**，所以 detail 只能写 ``source_public``（接口级），
    # 内部表名 / 责任方 / 目录路径一律只进日志。
    logger.info(
        "指标查询不足：metric=%s reason=%s blocked_by=%s source=%s",
        metric, REASON_DATA_SOURCE_UNAVAILABLE, spec.get("blocked_by"), spec["source"],
    )
    return _unavailable(
        REASON_DATA_SOURCE_UNAVAILABLE, metric=metric,
        detail=f"指标「{spec['label']}」的数据源（{spec['source_public']}）尚未接通，无法核实当前数值",
        unit=spec["unit"],
        entity_type=spec["entity_types"][0],
        period_start=start.isoformat(),
        period_end=end.isoformat(),
        grain=grain,
    )

def _locate_staging_file(self, document_id: str) -> Path | None:
    """定位上传时留下的 staging 原文件（重建立即可复用的输入源）。

    与 ``e_bridge.stage_and_accept_document`` 的落盘约定一致：优先
    ``settings.data_dir/knowledge_staging/{document_id}.*``，其次
    ``%TEMP%/dpart_knowledge_staging/{document_id}.*``。
    """
    import tempfile

    candidates: list[Path] = []
    base = Path(self._settings().data_dir) / "knowledge_staging"
    if base.exists():
        candidates.extend(sorted(base.glob(f"{document_id}.*")))
    tmp = Path(tempfile.gettempdir()) / "dpart_knowledge_staging"
    if tmp.exists():
        candidates.extend(sorted(tmp.glob(f"{document_id}.*")))
    for path in candidates:
        if path.is_file():
            return path
    return None

def _get_document_row(self, document_id: str) -> dict:
    """读 C 登记的文档行（身份 + 元数据）；后端不支持时返回空 dict。"""
    getter = getattr(self.store, "get_document", None)
    if getter is None:
        return {}
    try:
        return getter(document_id) or {}

def index_document(file_path: str, metadata: dict[str, Any]) -> dict[str, Any]:
    validated = DocumentMetadata.model_validate(metadata)
    if not metadata.get("document_id"):
        raise ValueError("C document_id is required")
    if not metadata.get("document_version"):
        raise ValueError("C document_version is required")
    payload = {"document_id": metadata["document_id"], "file_path": file_path,
               "version": metadata["document_version"],
               "document_version": metadata["document_version"],
               "metadata": validated.model_dump(mode="json")}
    result = submit("knowledge_index", payload)
    return {"document_id": metadata["document_id"], "index_status": "pending",
            "job_id": str(UUID(str(result["job_id"])))}


def process_document_index(file_path: str, metadata: dict[str, Any],
                           document_id: str | None = None) -> dict[str, Any]:
    document_id = document_id or metadata.get("document_id")

def process_knowledge_job(job_payload: dict) -> dict:
    document_id = job_payload["document_id"]
    metadata = DocumentMetadata.model_validate(job_payload["metadata"])
    document_version = job_payload.get("document_version", job_payload["metadata"].get("document_version"))
    index_version = job_payload["version"]
    if not isinstance(document_version, str) or not document_version.strip():
        raise ValueError("C source document_version is required")
    metadata_version = job_payload["metadata"].get("document_version")
    if metadata_version is not None and metadata_version != document_version:
        raise ValueError("Conflicting source document versions")
    if not isinstance(index_version, str) or not index_version.strip():
        raise ValueError("Index version is required")
    chunks = split_text(read_document(job_payload["file_path"]), document_id=document_id)
    if not chunks:
        raise ValueError("Document has no extractable text")
    payload = {"schema_version": ARTIFACT_SCHEMA_VERSION,
        "parser_version": PARSER_VERSION, "embedding_model_version": EMBEDDING_MODEL_VERSION,
        "documents": {document_id: {"document_version": document_version, "index_version": index_version,
        "metadata": metadata.model_dump(mode="json"),
        "chunks": [c.model_dump(mode="json") for c in chunks]}}}
    artifact = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
    return {"document_id": document_id, "version": job_payload["version"],
            "document_version": document_version, "index_version": index_version,
            "parser_version": PARSER_VERSION, "embedding_model_version": EMBEDDING_MODEL_VERSION,
            "chunk_count": len(chunks), "artifact_bytes": artifact,
            "artifact_sha256": hashlib.sha256(artifact).hexdigest(),
            "chunks": [{"chunk_no": c.order, "text": c.text,
                        "locator": {"chunk_id": c.chunk_id, "order": c.order}}
                       for c in chunks], "snapshot": payload}
